# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_SIZE": 32},
        ),
    ],
    key=["N"],
)
@triton.jit
def l1_norm_kernel(
    x_ptr,
    out_ptr,
    M,
    N,
    stride_xm,
    stride_xn,
    stride_om,
    stride_on,
    BLOCK_SIZE: tl.constexpr,
):
    row = tl.program_id(0)

    col_offsets = tl.arange(0, BLOCK_SIZE)
    row_x = x_ptr + row.to(tl.int64) * stride_xm
    row_o = out_ptr + row.to(tl.int64) * stride_om

    # Phase 1: compute sum(abs(x)) for this row
    abs_sum = 0.0
    for col_start in range(0, N, BLOCK_SIZE):
        cols = col_start + col_offsets
        mask = cols < N
        x = tl.load(row_x + cols * stride_xn, mask=mask, other=0.0).to(tl.float32)
        abs_sum += tl.sum(tl.abs(x), axis=0)

    # mean = sum(abs(x)) / N
    mean_val = abs_sum / N

    # Phase 2: normalize x / mean
    for col_start in range(0, N, BLOCK_SIZE):
        cols = col_start + col_offsets
        mask = cols < N
        x = tl.load(row_x + cols * stride_xn, mask=mask, other=0.0).to(tl.float32)
        out = x / mean_val
        tl.store(row_o + cols * stride_on, out.to(tl.bfloat16), mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        M, N = x.shape
        out = torch.empty_like(x)
        grid = (M,)
        l1_norm_kernel[grid](
            x,
            out,
            M,
            N,
            x.stride(0),
            x.stride(1),
            out.stride(0),
            out.stride(1),
        )
        return out
